function path(project="payments",repo="web",query:Record<string,string>={}){return `/v1/web/projects/${project}/repositories/${repo}/branches?`+new URLSearchParams({expectedOrgId:TEST_ORG,expectedRevision:"2",expectedProjectRevision:"1",...query}).toString();}
async function fixture(capable=true){
 let after=()=>{};let full=false;let missingRef=false,badRef=false;let installation=11,token404=false;let installationReads=0;let onInstallation=(count:number)=>{void count;};
 const requests:{method:string;path:string}[]=[];
 const fetchImplementation=(async(input:string|URL|Request,init?:RequestInit)=>{const u=new URL(typeof input==="string"?input:input instanceof URL?input.href:input.url);requests.push({method:init?.method??"GET",path:u.pathname+u.search});if(u.pathname.endsWith("/installation")){onInstallation(++installationReads);return Response.json({id:installation,account:{login:"acme"}});}if(u.pathname.includes("/access_tokens")&&token404)return Response.json({message:"private token404"},{status:404});if(u.pathname.includes("/access_tokens"))return Response.json({token:"synthetic-http-token"},{status:201});if(u.pathname==="/repos/acme/payments")return Response.json({id:22,full_name:"acme/payments"});if(u.pathname.includes("/git/ref/heads/")){after();if(missingRef)return Response.json({message:"private missing detail"},{status:404});const branch=decodeURIComponent(u.pathname.split("/git/ref/heads/")[1]!);return Response.json({ref:`refs/heads/${badRef?"wrong":branch}`,object:{type:"commit",sha:"c".repeat(40)}});}if(u.pathname.endsWith("/branches")){after();return Response.json(Array.from({length:full?100:2},(_,i)=>({name:full?`branch-${i}`:i===0?"main":"release/current",commit:{sha:"c".repeat(40)}})));}throw new Error("unexpected synthetic GitHub path");}) as typeof fetch;
 const sdk=new GitHubAppCredentialProvider({credentialRef:"github-app",appId:"123",getPrivateKey:async()=>pem,fetchImplementation,requireInstallationBound:async(org,id,repo)=>{return installationBindingCheck({documentClient:db,tableName:"state"})(org,id,repo);}});
 const developer:DeveloperApiConfiguration={issuer:CELL+"/v1/auth",env:"staging",signInTableName:"signin",methods:{slack:false,oidc:false,cloud:true},verifyAccessToken:async(authorization:string|undefined)=>authorization==="Bearer fixture"?{iss:CELL+"/v1/auth",aud:"agentx-developer",sub:WHO,sid:SID,amr:"cloud",env:"staging",org:TEST_ORG,org_role:"owner"}:{},channelMembers:async()=>({ok:true,memberOf:[]})};
 const auditCapture=capturingAuditDeps();const h=await createAdminBroker({developer,extra:{audit:auditCapture.audit,...(capable?{githubPullRequests:sdk}:{})}});const db=h.db;auditCapture.attach(db);auditCapture.audit.documentClient=db as never;
 function person(id=WHO,sid=SID,org=TEST_ORG,role:"owner"|"admin"|"member"="owner"){seedMembership(h.db,id,{orgId:org,role});h.db.set({...orgMetaKey(org),orgId:org,name:"Company",plan:"team"});h.db.set({pk:`DEVELOPER#${id}`,sk:"META",developerId:id,displayName:"Fixture person",provider:"cloud"});h.db.set({pk:`SESSION#${sid}`,sk:"META",sessionId:sid,developerId:id,amr:"cloud",startedAt:new Date(NOW-60000).toISOString(),endsAt:Math.floor(NOW/1000)+3600,reviewExpiresAt:Math.floor(NOW/1000)+3600});}person();
 function project(name="payments",org=TEST_ORG){const definition=StoredProjectDefinitionSchema.parse({name,revision:1,repositories:["web","api"].map((name)=>({name,url:"https://github.com/acme/payments.git",path:`repo/${name}`,defaultBranch:"main",credentialRef:"github-app",installationId:11,githubRepositoryId:22})),setup:[],readiness:[],orchestratorInstructions:"Private fixture config"});h.db.set({...orgProjectCatalogKey(org,name),entityType:"PROJECT_CATALOG",name,latestRevision:1});h.db.set({...projectRevisionKey(org,name,1),entityType:"PROJECT",definition});h.db.set({...projectMetaKey(org,name),entityType:"PROJECT_META",name,status:"active",archiveRevision:2});}project();project("other");project("payments",B);h.db.set({...githubInstallationKey(11),orgId:TEST_ORG,status:"active"});
 async function call(route=path(),headers:Record<string,string|undefined>={cookie:COOKIE},method="GET",payload?:unknown){const u=new URL(route,CELL),response=await h.handler({rawPath:u.pathname,rawQueryString:u.search.slice(1),routeKey:u.pathname.startsWith("/v1/web/")?"ANY /v1/web/{proxy+}":"ANY /v1/app/{proxy+}",headers,...(payload===undefined?{}:{body:JSON.stringify(payload)}),requestContext:{requestId:"branch-http-fixture",http:{method}}});return{status:response.statusCode,body:JSON.parse(response.body) as Record<string,unknown>};}
 return{...h,sdk,requests,call,person,project,orgCounter(org=TEST_ORG){return h.db.get({pk:orgScoped(org,"WORKING_BRANCH_ORG_PAGES"),sk:"ALL"});},onList(run:()=>void){after=run;},missingRef(){missingRef=true;},badRef(){badRef=true;},installation(id:number){installation=id;},token404(){token404=true;},onInstallation(run:(count:number)=>void){onInstallation=run;},full(){full=true;},listed(){return requests.filter(r=>r.path.startsWith("/repos/acme/payments/branches")).length;},minted(){return requests.filter(r=>r.method==="POST").length;},counter(org=TEST_ORG,id=WHO){return h.db.get({pk:orgScoped(org,"WORKING_BRANCH_PAGES"),sk:id});}};
}
it("serves scoped branch names through real cookie auth and SDK/factories, preserving project state",async()=>{const f=await fixture(),before=f.db.get(projectMetaKey(TEST_ORG,"payments")),result=await f.call();expect(result.status,JSON.stringify(result.body)).toBe(200);expect(result.body).toMatchObject({orgId:TEST_ORG,project:"payments",repository:"web",expectedRevision:2,expectedProjectRevision:1,branches:["main","release/current"],page:1,mayHaveMore:false,limitReached:false});expect(f.listed()).toBe(1);expect(f.db.get(projectMetaKey(TEST_ORG,"payments"))).toEqual(before);expect(f.db.transactions()).toEqual([]);expect(f.counter()).toMatchObject({count:1});expect(JSON.stringify(result.body)).not.toMatch(/synthetic-http-token|Private fixture|credentialRef|"commit"|https:/);});
