for(const role of ["member","contributor","viewer"])it(`refuses ${role} before project existence for present and missing targets`,async()=>{const f=await fixture();f.person(WHO,SID,TEST_ORG,"member");if(role!=="member")f.db.set({...projectMemberKey(TEST_ORG,WHO,"payments"),role:role==="viewer"?"viewer":"developer",projectRole:role,projectName:"payments"});const send=f.db.send.bind(f.db),reads:string[]=[];f.db.send=async c=>{if(c.constructor.name==="GetCommand")reads.push(JSON.stringify(c.input.Key));return send(c);};for(const target of ["payments","absent"]){expect((await f.call(path(target))).status).toBe(403);expect(reads).not.toContain(JSON.stringify(orgProjectCatalogKey(TEST_ORG,target)));}expect(f.counter()).toBeUndefined();expect(f.minted()).toBe(0);});
it("lets an owner distinguish missing only within their company",async()=>{const f=await fixture();expect((await f.call(path("absent"))).status).toBe(404);expect((await f.call()).status).toBe(200);});
for(const query of ["expectedOrgId=bad&expectedRevision=2&expectedProjectRevision=1","expectedOrgId="+TEST_ORG+"&expectedRevision=02&expectedProjectRevision=1","expectedOrgId="+TEST_ORG+"&expectedRevision=-1&expectedProjectRevision=1","expectedOrgId="+TEST_ORG+"&expectedRevision=2&expectedProjectRevision=1&url=https://foreign.example","expectedOrgId="+TEST_ORG+"&expectedRevision=2&expectedRevision=2&expectedProjectRevision=1","expectedOrgId="+TEST_ORG+"&expectedRevision=2&expectedProjectRevision=1&page=2","expectedOrgId="+TEST_ORG+"&expectedRevision=2&expectedProjectRevision=1&repository=api","expectedOrgId="+TEST_ORG+"&expectedRevision=2.0&expectedProjectRevision=1",""])it(`strictly refuses query ${query}`,async()=>{const f=await fixture();expect((await f.call(path().split("?")[0]+"?"+query)).status).toBe(400);expect(f.minted()).toBe(0);expect(f.counter()).toBeUndefined();});
