// B32 browser-only save/status exposure, exercised through the real cookie boundary.
const savePath="/v1/web/projects/payments/working-branches", saveId="33333333-3333-4333-8333-333333333333";
const saveBody=()=>({requestId:saveId,expectedOrgId:TEST_ORG,expectedRevision:2,expectedProjectRevision:1,repository:"web",branch:"release/current",expectedCommit:"c".repeat(40)});
const saveHeaders=()=>({cookie:COOKIE,origin:CELL,[APP_CSRF_HEADER]:appCsrfTokenFor(SID)});
const statusPath=(uuid=saveId)=>savePath+"/requests/"+uuid;
async function saveFixture(){const f=await fixture();const key=projectRevisionKey(TEST_ORG,"payments",1);f.db.set({...f.db.get(key),runtimeBinding:{fixture:true}});return f;}
for(const [method,route] of [["POST",savePath],["GET",statusPath()]] as const)it(`B32 refuses bearer ${method} before existence`,async()=>{const f=await saveFixture();const r=await f.call(route.replace("/v1/web/","/v1/app/").replace("payments","absent"),{authorization:"Bearer fixture"},method,method==="POST"?saveBody():undefined);expect(r.status).toBe(403);expect(errorOf(r.body).code).toBe("FORBIDDEN");expect(f.minted()).toBe(0);expect(f.db.transactions()).toEqual([]);});
for(const headers of [{cookie:COOKIE},{...saveHeaders(),origin:"https://foreign.example"},{...saveHeaders(),[APP_CSRF_HEADER]:"bad"}])it("B32 refuses cookie POST without valid Origin/CSRF",async()=>{const f=await saveFixture();expect((await f.call(savePath,headers,"POST",saveBody())).status).toBe(403);expect(f.minted()).toBe(0);});
for(const role of ["owner","admin","maintainer","member","viewer","revoked"])it(`B32 save live role ${role}`,async()=>{const f=await saveFixture();f.person(WHO,SID,TEST_ORG,role==="owner"||role==="admin"?role:"member");if(role==="maintainer"||role==="viewer")f.db.set({...projectMemberKey(TEST_ORG,WHO,"payments"),role:role==="viewer"?"viewer":"developer",projectRole:role,projectName:"payments"});if(role==="revoked")f.db.delete(orgMemberKey(TEST_ORG,WHO));const r=await f.call(savePath,saveHeaders(),"POST",saveBody());expect(r.status,JSON.stringify(r.body)).toBe(["owner","admin","maintainer"].includes(role)?200:403);if(r.status!==200)expect(f.minted()).toBe(0);});
it("B32 saves, reads status, and deliberate same-UUID resend has one revision and audit",async()=>{const f=await saveFixture();const first=await f.call(savePath,saveHeaders(),"POST",saveBody());expect(first.status,JSON.stringify(first.body)).toBe(200);const minted=f.minted(),count=f.counter()?.count;const status=await f.call(statusPath());expect(status.status).toBe(200);expect(status.body.receipt).toEqual(first.body.receipt);const replay=await f.call(savePath,saveHeaders(),"POST",saveBody());expect(replay.status).toBe(200);expect(replay.body.replayed).toBe(true);expect(f.minted()).toBe(minted);expect(f.counter()?.count).toBe(count);expect(f.db.get(orgProjectCatalogKey(TEST_ORG,"payments"))).toMatchObject({latestRevision:2});expect(f.db.get(projectRevisionKey(TEST_ORG,"payments",3))).toBeUndefined();expect(f.db.transactions()).toHaveLength(1);});
it("B32 foreign and missing status are identical with no provider calls",async()=>{const f=await saveFixture();expect((await f.call(savePath,saveHeaders(),"POST",saveBody())).status).toBe(200);f.person(OTHER,SID2);const headers={cookie:`__Host-agentx_review_session=${SID2}`},before=f.minted();const foreign=await f.call(statusPath(),headers),missing=await f.call(statusPath("44444444-4444-4444-8444-444444444444"),headers);expect(foreign.status).toBe(404);expect(missing.status).toBe(404);expect(foreign.body.error).toEqual(missing.body.error);expect(f.minted()).toBe(before);});
it("B32 moved branch refuses exact commit",async()=>{const f=await saveFixture();const r=await f.call(savePath,saveHeaders(),"POST",{...saveBody(),expectedCommit:"d".repeat(40)});expect(r.status).toBe(409);expect(errorOf(r.body).code).toBe("CHANGE_STALE");expect(f.db.get(projectRevisionKey(TEST_ORG,"payments",2))).toBeUndefined();});
it("B32 shared exhausted person budget refuses before mint",async()=>{const f=await saveFixture();for(let i=0;i<10;i++)expect((await f.call()).status).toBe(200);const before=f.minted();expect((await f.call(savePath,saveHeaders(),"POST",saveBody())).status).toBe(429);expect(f.minted()).toBe(before);});
it("B32 status has an independent bounded person read budget",async()=>{const f=await saveFixture();for(let i=0;i<30;i++)expect((await f.call(statusPath())).status).toBe(404);expect((await f.call(statusPath())).status).toBe(429);expect(f.minted()).toBe(0);expect(f.counter()).toBeUndefined();});

it("B32 canonical project detail reports saved setting separately from default",async()=>{const f=await saveFixture();expect((await f.call(savePath,saveHeaders(),"POST",saveBody())).status).toBe(200);const r=await f.call("/v1/web/projects/payments");expect(r.status).toBe(200);expect(r.body.savedWorkingBranches).toEqual([{repository:"web",fullName:"acme/payments",branch:"release/current",commit:"c".repeat(40)}]);expect((r.body.repositories as {defaultBranch:string}[])[0]!.defaultBranch).toBe("main");});

it("B32 live maintainer grant removal during provider read prevents commit",async()=>{const f=await saveFixture();f.person(WHO,SID,TEST_ORG,"member");const key=projectMemberKey(TEST_ORG,WHO,"payments");f.db.set({...key,role:"developer",projectRole:"maintainer",projectName:"payments"});f.onList(()=>f.db.delete(key));expect((await f.call(savePath,saveHeaders(),"POST",saveBody())).status).toBe(403);expect(f.db.get(projectRevisionKey(TEST_ORG,"payments",2))).toBeUndefined();});
it("B32 delayed original cannot commit after another UUID saved the reviewed revision",async()=>{const f=await saveFixture();const fresh={...saveBody(),requestId:"55555555-5555-4555-8555-555555555555"};expect((await f.call(savePath,saveHeaders(),"POST",fresh)).status).toBe(200);const before=f.minted();expect((await f.call(savePath,saveHeaders(),"POST",saveBody())).status).toBe(409);expect(f.minted()).toBe(before);expect(f.db.transactions()).toHaveLength(1);});

it("B32 review refuses a foreign-company same-name save before provider or writes",async()=>{const f=await saveFixture();f.person(WHO,SID,B);const r=await f.call(savePath,saveHeaders(),"POST",saveBody());expect(r.status).toBe(409);expect(errorOf(r.body).code).toBe("CHANGE_STALE");expect(f.minted()).toBe(0);expect(f.db.transactions()).toEqual([]);});

it("B32 review member maintainer reads only own project settings and cannot save another project",async()=>{const f=await saveFixture();f.person(WHO,SID,TEST_ORG,"member");f.db.set({...projectMemberKey(TEST_ORG,WHO,"payments"),role:"developer",projectRole:"maintainer",projectName:"payments"});const own=await f.call("/v1/web/projects/payments");expect(own.status).toBe(200);expect(own.body.myRole).toBe("maintainer");expect(own.body).toHaveProperty("settings");for(const route of ["/v1/web/projects/other",savePath.replace("payments","other")]){const r=await f.call(route,saveHeaders(),route.includes("working-branches")?"POST":"GET",route.includes("working-branches")?saveBody():undefined);expect([403,404]).toContain(r.status);expect(r.body).not.toHaveProperty("settings");}expect(f.minted()).toBe(0);expect(f.db.transactions()).toEqual([]);});
